);;

-- ACDOCP
CREATE TABLE `ACDOCP` (
  `tenant_id` varchar(20) NOT NULL COMMENT "Multi-tenant identifier",
  `RYEAR` varchar(4) NOT NULL COMMENT "Fiscal Year — PARTITION COLUMN (joins ACDOCA.GJAHR)",
  `RLDNR` varchar(2) NOT NULL COMMENT "Ledger",
  `REQTSN` varchar(23) NOT NULL COMMENT "Request Transaction Sequence No (key)",
  `DATAPAKID` varchar(6) NOT NULL COMMENT "Data Package ID (key)",
  `RECORD` int(11) NOT NULL COMMENT "Record No within package (key)",
  `RCLNT` varchar(3) NULL COMMENT "SAP Client",
  `POPER` varchar(3) NULL COMMENT "Posting Period",
  `FISCYEARPER` varchar(7) NULL COMMENT "Fiscal Year / Period",
  `BUDAT` varchar(8) NULL COMMENT "Posting Date (source yyyymmdd string)",
  `PERIV` varchar(2) NULL COMMENT "Fiscal Year Variant",
  `CATEGORY` varchar(10) NULL COMMENT "Plan Category (budget / forecast / ...)",
  `KOKRS` varchar(4) NULL COMMENT "Controlling Area",
  `KTOPL` varchar(4) NULL COMMENT "Chart of Accounts",
  `RBUKRS` varchar(4) NULL COMMENT "Company Code",
  `RACCT` varchar(10) NULL COMMENT "G/L Account = Cost Element (S/4)",
  `RCNTR` varchar(10) NULL COMMENT "Cost Center",
  `PRCTR` varchar(10) NULL COMMENT "Profit Center",
  `RFAREA` varchar(16) NULL COMMENT "Functional Area",
  `RBUSA` varchar(4) NULL COMMENT "Business Area",
  `SEGMENT` varchar(10) NULL COMMENT "Segment",
  `AUFNR` varchar(12) NULL COMMENT "Order Number",
  `LSTAR` varchar(6) NULL COMMENT "Activity Type",
  `WERKS` varchar(4) NULL COMMENT "Plant",
  `MATNR` varchar(40) NULL COMMENT "Material",
  `KUNNR` varchar(10) NULL COMMENT "Customer",
  `KDAUF` varchar(10) NULL COMMENT "Sales Order",
  `KDPOS` varchar(6) NULL COMMENT "Sales Order Item",
  `PS_POSID` varchar(24) NULL COMMENT "WBS Element",
  `PS_PSPID` varchar(24) NULL COMMENT "Project Definition",
  `RWCUR` varchar(5) NULL COMMENT "Transaction Currency",
  `RHCUR` varchar(5) NULL COMMENT "Local (company-code) Currency",
  `RKCUR` varchar(5) NULL COMMENT "Group Currency",
  `WSL` decimal(23, 2) NULL COMMENT "Plan Amount in Transaction Currency",
  `HSL` decimal(23, 2) NULL COMMENT "Plan Amount in Local Currency  (<- plan figure used in MV)",
  `KSL` decimal(23, 2) NULL COMMENT "Plan Amount in Group Currency",
  `OSL` decimal(23, 2) NULL COMMENT "Plan Amount in further currency",
  `RVUNIT` varchar(3) NULL COMMENT "Quantity Unit",
  `RRUNIT` varchar(3) NULL COMMENT "Base Unit of Measure",
  `VMSL` decimal(23, 3) NULL COMMENT "Plan Quantity",
  `RMSL` decimal(23, 3) NULL COMMENT "Plan Quantity in Base Unit",
  `USNAM` varchar(12) NULL COMMENT "User Name",
  `AWTYP` varchar(5) NULL COMMENT "Reference Transaction Type",
  `created_at` datetime NOT NULL COMMENT "ETL Pipeline Load Timestamp"
) ENGINE=OLAP 
PRIMARY KEY(`tenant_id`, `RYEAR`, `RLDNR`, `REQTSN`, `DATAPAKID`, `RECORD`)
COMMENT "SAP ACDOCP — Universal Journal plan line items"
PARTITION BY (`RYEAR`)
DISTRIBUTED BY HASH(`tenant_id`, `REQTSN`) BUCKETS 16 
PROPERTIES (
"bloom_filter_columns" = "AUFNR, RACCT, RCNTR",
"compression" = "LZ4",
"enable_persistent_index" = "true",
"fast_schema_evolution" = "true",
"replicated_storage" = "true",
"replication_num" = "1"
);;

-- ADRC
CREATE TABLE `ADRC` (
  `tenant_id` varchar(20) NOT NULL COMMENT "",
  `ADDRNUMBER` varchar(20) NOT NULL COMMENT "",
  `DATE_FROM` date NOT NULL COMMENT "",
  `NATION` varchar(2) NOT NULL COMMENT "",
  `NAME1` varchar(80) NULL COMMENT "",
  `NAME2` varchar(80) NULL COMMENT "",
  `CITY1` varchar(80) NULL COMMENT "City",
  `POST_CODE1` varchar(20) NULL COMMENT "Postal code",
  `STREET` varchar(120) NULL COMMENT "",
  `HOUSE_NUM1` varchar(20) NULL COMMENT "",
  `COUNTRY` varchar(6) NULL COMMENT "",
  `REGION` varchar(6) NULL COMMENT "",
  `TEL_NUMBER` varchar(60) NULL COMMENT "",
  `SMTP_ADDR` varchar(120) NULL COMMENT "",
  `created_at` datetime NOT NULL COMMENT "",
  `updated_at` datetime NOT NULL COMMENT ""
) ENGINE=OLAP 
PRIMARY KEY(`tenant_id`, `ADDRNUMBER`, `DATE_FROM`, `NATION`)
COMMENT "SAP ADRC — central addresses"
DISTRIBUTED BY HASH(`tenant_id`, `ADDRNUMBER`) BUCKETS 16 
PROPERTIES (
"bloom_filter_columns" = "CITY1, POST_CODE1",
"compression" = "LZ4",
"enable_persistent_index" = "true",
"fast_schema_evolution" = "true",
"replicated_storage" = "true",
"replication_num" = "1"
);;

-- AFIH
CREATE TABLE `AFIH` (
  `tenant_id` varchar(20) NOT NULL COMMENT "",
  `AUFNR` varchar(24) NOT NULL COMMENT "",
  `EQUNR` varchar(36) NULL COMMENT "Equipment",
  `TPLNR` varchar(60) NULL COMMENT "Functional location",
  `GEWRK` varchar(16) NULL COMMENT "Main work center",
  `PRIOK` varchar(2) NULL COMMENT "Priority",
  `ARTPR` varchar(4) NULL COMMENT "",
  `IWERK` varchar(8) NULL COMMENT "Maintenance plant",
  `INGRP` varchar(6) NULL COMMENT "Planner group",
  `ILART` varchar(6) NULL COMMENT "Maint activity type",
  `ADDAT` date NULL COMMENT "",
  `OBJNR` varchar(44) NULL COMMENT "",
  `created_at` datetime NOT NULL COMMENT "",
  `updated_at` datetime NOT NULL COMMENT ""
) ENGINE=OLAP 
PRIMARY KEY(`tenant_id`, `AUFNR`)
COMMENT "SAP AFIH — maintenance order header"
DISTRIBUTED BY HASH(`tenant_id`, `AUFNR`) BUCKETS 16 
PROPERTIES (
"bloom_filter_columns" = "EQUNR, TPLNR",
"colocate_with" = "g_prodorder_v2",
"compression" = "LZ4",
"enable_persistent_index" = "true",
"fast_schema_evolution" = "true",
"replicated_storage" = "true",
"replication_num" = "1"
);;

