) ENGINE=OLAP 
PRIMARY KEY(`tenant_id`, `EBELN`, `BEDAT`)
COMMENT "SAP EKKO — lakehouse upsert,
partition: BEDAT"
PARTITION BY date_trunc('month', `BEDAT`)
DISTRIBUTED BY HASH(`tenant_id`, `EBELN`) BUCKETS 32 
PROPERTIES (
"bloom_filter_columns" = "KNUMV, LIFNR",
"colocate_with" = "g_po_v2",
"compression" = "LZ4",
"enable_persistent_index" = "true",
"fast_schema_evolution" = "true",
"replicated_storage" = "true",
"replication_num" = "1"
);;

