-- EORD
CREATE TABLE `EORD` (
  `tenant_id` varchar(20) NOT NULL COMMENT "Multi-tenant identifier",
  `MATNR` varchar(80) NOT NULL COMMENT "Material → MARA",
  `WERKS` varchar(8) NOT NULL COMMENT "Plant",
  `ZEORD` varchar(10) NOT NULL COMMENT "Source List Record Number",
  `MANDT` varchar(6) NULL COMMENT "SAP Client",
  `ERDAT` date NULL COMMENT "Created On",
  `ERNAM` varchar(24) NULL COMMENT "Created By",
  `VDATU` date NULL COMMENT "Blocked Flag: 2 = Blocked",
  `BDATU` date NULL COMMENT "Valid To",
  `LIFNR` varchar(20) NULL COMMENT "Vendor → LFA1",
  `FLIFN` varchar(2) NULL COMMENT "SAP standard field",
  `EBELN` varchar(20) NULL COMMENT "Outline Agreement",
  `EBELP` varchar(10) NULL COMMENT "Outline Agreement Item",
  `FEBEL` varchar(2) NULL COMMENT "SAP standard field",
  `RESWK` varchar(8) NULL COMMENT "Supplying Plant (STO)",
  `FRESW` varchar(2) NULL COMMENT "SAP standard field",
  `EMATN` varchar(160) NULL COMMENT "SAP standard field",
  `NOTKZ` varchar(2) NULL COMMENT "SAP standard field",
  `EKORG` varchar(8) NULL COMMENT "Purchasing Organization",
  `VRTYP` varchar(2) NULL COMMENT "SAP standard field",
  `EORTP` varchar(2) NULL COMMENT "SAP standard field",
  `AUTET` varchar(2) NULL COMMENT "SAP standard field",
  `MEINS` varchar(6) NULL COMMENT "Unit of Measure",
  `LOGSY` varchar(20) NULL COMMENT "SAP standard field",
  `SOBKZ` varchar(2) NULL COMMENT "SAP standard field",
  `SRM_CONTRACT_ID` varchar(20) NULL COMMENT "SAP standard field",
  `SRM_CONTRACT_ITM` varchar(20) NULL COMMENT "SAP standard field",
  `DUMMY_EORD_INCL_EEW_PS` varchar(2) NULL COMMENT "SAP standard field",
  `LASTCHANGEDATETIME` decimal(21, 7) NULL COMMENT "SAP standard field",
  `created_at` datetime NOT NULL COMMENT "ETL Pipeline Load Timestamp",
  INDEX idx_eord_meins (`MEINS`) USING BITMAP COMMENT 'Bitmap on MEINS'
) ENGINE=OLAP 
PRIMARY KEY(`tenant_id`, `MATNR`, `WERKS`, `ZEORD`)
COMMENT "SAP EORD — lakehouse upsert, partition: none"
DISTRIBUTED BY HASH(`tenant_id`, `MATNR`) BUCKETS 16 
PROPERTIES (
"bloom_filter_columns" = "EBELN, LIFNR",
"colocate_with" = "g_material_v2",
"compression" = "LZ4",
"enable_persistent_index" = "true",
"fast_schema_evolution" = "true",
"replicated_storage" = "true",
"replication_num" = "1"
);;

-- EQUI
