-- JCDS
CREATE TABLE `JCDS` (
  `tenant_id` varchar(20) NOT NULL COMMENT "",
  `OBJNR` varchar(44) NOT NULL COMMENT "",
  `STAT` varchar(10) NOT NULL COMMENT "",
  `CHGNR` varchar(6) NOT NULL COMMENT "",
  `UDATE` date NOT NULL COMMENT "Change date — PARTITION key",
  `UTIME` varchar(12) NULL COMMENT "",
  `USNAM` varchar(24) NULL COMMENT "",
  `INACT` varchar(2) NULL COMMENT "Status inactive flag",
  `CHIND` varchar(2) NULL COMMENT "",
  `created_at` datetime NOT NULL COMMENT "",
  `updated_at` datetime NOT NULL COMMENT ""
) ENGINE=OLAP 
PRIMARY KEY(`tenant_id`, `OBJNR`, `STAT`, `CHGNR`, `UDATE`)
COMMENT "SAP JCDS — status change documents"
PARTITION BY date_trunc('month', `UDATE`)
DISTRIBUTED BY HASH(`tenant_id`, `OBJNR`) BUCKETS 32 
PROPERTIES (
"compression" = "ZSTD",
"enable_persistent_index" = "true",
"fast_schema_evolution" = "true",
"replicated_storage" = "true",
"replication_num" = "1"
);;

-- JEST
CREATE TABLE `JEST` (
  `tenant_id` varchar(20) NOT NULL COMMENT "Multi-tenant identifier",
