) ENGINE=OLAP 
PRIMARY KEY(`tenant_id`, `OBJNR`, `STAT`)
COMMENT "SAP JEST — lakehouse upsert, partition: none"
DISTRIBUTED BY HASH(`tenant_id`, `OBJNR`) BUCKETS 16 
PROPERTIES (
"compression" = "LZ4",
"enable_persistent_index" = "true",
"fast_schema_evolution" = "true",
"replicated_storage" = "true",
"replication_num" = "1"
);;

