  INDEX idx_likp_lifsk (`LIFSK`) USING BITMAP COMMENT 'Bitmap on LIFSK',
  INDEX idx_likp_waerk (`WAERK`) USING BITMAP COMMENT 'Bitmap on WAERK',
  INDEX idx_likp_gbstk (`GBSTK`) USING BITMAP COMMENT 'Bitmap on GBSTK'
) ENGINE=OLAP 
PRIMARY KEY(`tenant_id`, `VBELN`, `ERDAT`)
COMMENT "SAP LIKP — lakehouse upsert, partition: ERDAT"
PARTITION BY date_trunc('month', `ERDAT`)
DISTRIBUTED BY HASH(`tenant_id`, `VBELN`) BUCKETS 16 
PROPERTIES (
"bloom_filter_columns" = "BOLNR, KUNAG, KUNNR, LIFEX, XBLNR",
"colocate_with" = "g_delivery_v2",
"compression" = "LZ4",
"enable_persistent_index" = "true",
"fast_schema_evolution" = "true",
"replicated_storage" = "true",
"replication_num" = "1"
);;

