PRIMARY KEY(`tenant_id`, `VBELN`, `POSNR`, `ERDAT`)
COMMENT "SAP LIPS — lakehouse upsert, partition: ERDAT"
PARTITION BY date_trunc('month', `ERDAT`)
DISTRIBUTED BY HASH(`tenant_id`, `VBELN`) BUCKETS 16 
PROPERTIES (
"bloom_filter_columns" = "CHARG, KDMAT, MATNR, VGBEL",
"colocate_with" = "g_delivery_v2",
"compression" = "LZ4",
"enable_persistent_index" = "true",
"fast_schema_evolution" = "true",
"replicated_storage" = "true",
"replication_num" = "1"
);;

-- MAKT
CREATE TABLE `MAKT` (
  `tenant_id` varchar(20) NOT NULL COMMENT "",
  `MATNR` varchar(80) NOT NULL COMMENT "Material Number",
  `SPRAS` varchar(8) NOT NULL COMMENT "Language Key",
  `MANDT` varchar(6) NULL COMMENT "SAP Client",
  `MAKTX` varchar(160) NULL COMMENT "Material Description",
  `MAKTG` varchar(160) NULL COMMENT "Material Description (Upper)",
  `created_at` datetime NOT NULL COMMENT "",
  `updated_at` datetime NOT NULL COMMENT "",
  INDEX idx_makt_spras (`SPRAS`) USING BITMAP COMMENT 'Bitmap on SPRAS'
) ENGINE=OLAP 
PRIMARY KEY(`tenant_id`, `MATNR`, `SPRAS`)
COMMENT "SAP MAKT — lakehouse upsert,
partition: none"
DISTRIBUTED BY HASH(`tenant_id`, `MATNR`) BUCKETS 16 
PROPERTIES (
"colocate_with" = "g_material_v2",
"compression" = "LZ4",
"enable_persistent_index" = "true",
"fast_schema_evolution" = "true",
"replicated_storage" = "true",
"replication_num" = "1"
);;

