  `created_at` datetime NOT NULL COMMENT "ETL Pipeline Load Timestamp",
  INDEX idx_matdoc_waers (`WAERS`) USING BITMAP COMMENT 'Bitmap on WAERS',
  INDEX idx_matdoc_meins (`MEINS`) USING BITMAP COMMENT 'Bitmap on MEINS',
  INDEX idx_matdoc_bwart (`BWART`) USING BITMAP COMMENT 'Bitmap on BWART',
  INDEX idx_matdoc_xauto (`XAUTO`) USING BITMAP COMMENT 'Bitmap on XAUTO',
  INDEX idx_matdoc_shkzg (`SHKZG`) USING BITMAP COMMENT 'Bitmap on SHKZG',
  INDEX idx_matdoc_elikz (`ELIKZ`) USING BITMAP COMMENT 'Bitmap on ELIKZ',
  INDEX idx_matdoc_blart (`BLART`) USING BITMAP COMMENT 'Bitmap on BLART'
) ENGINE=OLAP 
PRIMARY KEY(`tenant_id`, `MBLNR`, `MJAHR`, `ZEILE`, `BUDAT`)
COMMENT "SAP MATDOC — lakehouse upsert, partition: BUDAT"
PARTITION BY date_trunc('month', `BUDAT`)
DISTRIBUTED BY HASH(`tenant_id`, `MBLNR`) BUCKETS 16 
PROPERTIES (
"bloom_filter_columns" = "AUFNR, CHARG, EBELN, KUNNR, LIFNR, MATNR, XBLNR",
"colocate_with" = "g_matdoc_v2",
"compression" = "LZ4",
"enable_persistent_index" = "true",
"fast_schema_evolution" = "true",
"replicated_storage" = "true",
"replication_num" = "1"
);;

