PRIMARY KEY(`tenant_id`, `VBELN`, `FKDAT`)
COMMENT "SAP VBRK — lakehouse upsert,
partition: FKDAT"
PARTITION BY date_trunc('month', `FKDAT`)
DISTRIBUTED BY HASH(`tenant_id`, `VBELN`) BUCKETS 16 
PROPERTIES (
"bloom_filter_columns" = "BELNR, KNUMV, KUNAG, KUNRG, XBLNR",
"colocate_with" = "g_billing_v2",
"compression" = "LZ4",
"enable_persistent_index" = "true",
"fast_schema_evolution" = "true",
"replicated_storage" = "true",
"replication_num" = "1"
);;

