-- vw_ai_control_center
CREATE VIEW `vw_ai_control_center` (`tenant_id`, `domain`, `entity_id`, `entity_name`, `status`, `severity`, `metric_value`, `metric_label`, `reason`, `recommended_action`) SECURITY NONE AS SELECT
    tenant_id, 'CUSTOMER' AS domain,
    customer AS entity_id, customer_name AS entity_name,
    CASE segment
      WHEN 'AT_RISK_STOPPED' THEN 'CRITICAL'
      WHEN 'DECLINING'       THEN 'RISK'
      WHEN 'CREDIT_BLOCKED'  THEN 'RISK'
      WHEN 'LOW_MARGIN'      THEN 'WATCH'
      ELSE 'GOOD' END                                              AS status,
    CASE segment WHEN 'AT_RISK_STOPPED' THEN 4
                 WHEN 'DECLINING' THEN 3 WHEN 'CREDIT_BLOCKED' THEN 3
                 WHEN 'LOW_MARGIN' THEN 2 ELSE 1 END               AS severity,
    rev_12m                                                        AS metric_value,
    'Revenue last 12m'                                            AS metric_label,
    reason                                                         AS reason,
    CASE segment
      WHEN 'AT_RISK_STOPPED' THEN 'Win-back outreach within 7 days, check open returns/complaints'
      WHEN 'DECLINING'       THEN 'Account review call, investigate competitor or quality issue'
      WHEN 'CREDIT_BLOCKED'  THEN 'Clear overdue with AR before next order, review credit limit'
      WHEN 'LOW_MARGIN'      THEN 'Renegotiate pricing/discount, review product mix'
      WHEN 'GROWING_LOYAL'   THEN 'Protect & grow: upsell / cross-sell'
      ELSE 'Maintain relationship' END                            AS recommended_action
FROM mv_ai_customer_health
 
UNION ALL
 
-- VENDOR
SELECT
    tenant_id, 'VENDOR' AS domain,
    vendor AS entity_id, vendor_name AS entity_name,
    CASE WHEN max_days_late > 15 THEN 'CRITICAL'
         WHEN overdue_items > 0  THEN 'RISK'
         ELSE 'GOOD' END                                          AS status,
    CASE WHEN max_days_late > 15 THEN 4
         WHEN overdue_items > 0  THEN 3 ELSE 1 END                AS severity,
    overdue_value                                                 AS metric_value,
    'Overdue PO value'                                           AS metric_label,
    CASE WHEN overdue_items > 0
         THEN CONCAT(CAST(overdue_items AS STRING), ' overdue lines, worst ',
                     CAST(max_days_late AS STRING), ' days late')
         ELSE 'All open POs on schedule' END                      AS reason,
    CASE WHEN max_days_late > 15 THEN 'Escalate to vendor mgmt, activate backup source, expedite'
         WHEN overdue_items > 0  THEN 'Chase delivery, confirm new committed date'
         ELSE 'No action' END                                     AS recommended_action
FROM mv_ai_vendor_risk
 
UNION ALL
 
-- INVENTORY
SELECT
    tenant_id, 'INVENTORY' AS domain,
    CONCAT(material, '@', plant) AS entity_id, material_desc AS entity_name,
    CASE stock_state
      WHEN 'STOCKOUT_IMMINENT' THEN 'CRITICAL'
      WHEN 'DEAD_STOCK'        THEN 'RISK'
      WHEN 'STOCKOUT_RISK'     THEN 'RISK'
      WHEN 'OVERSTOCK'         THEN 'WATCH'
      ELSE 'GOOD' END                                             AS status,
    CASE stock_state WHEN 'STOCKOUT_IMMINENT' THEN 4
                     WHEN 'DEAD_STOCK' THEN 3 WHEN 'STOCKOUT_RISK' THEN 3
                     WHEN 'OVERSTOCK' THEN 2 ELSE 1 END           AS severity,
    coverage_days                                                 AS metric_value,
    'Days of cover'                                              AS metric_label,
    CASE stock_state
      WHEN 'DEAD_STOCK' THEN 'No consumption in 90 days, stock still held'
      WHEN 'STOCKOUT_IMMINENT' THEN CONCAT('Only ', CAST(ROUND(coverage_days) AS STRING), ' days of cover')
      WHEN 'STOCKOUT_RISK' THEN CONCAT(CAST(ROUND(coverage_days) AS STRING), ' days of cover')
      WHEN 'OVERSTOCK' THEN 'Over a year of cover on hand'
      ELSE 'Coverage healthy' END                                 AS reason,
    CASE stock_state
      WHEN 'DEAD_STOCK'        THEN 'Stop replenishment, liquidate/return, review MRP'
      WHEN 'STOCKOUT_IMMINENT' THEN 'Expedite open PO/production now, raise safety stock'
      WHEN 'STOCKOUT_RISK'     THEN 'Review reorder point, confirm inbound supply'
      WHEN 'OVERSTOCK'         THEN 'Reduce reorder qty, review forecast'
      ELSE 'No action' END                                        AS recommended_action
FROM mv_ai_inventory_risk
WHERE stock_state <> 'HEALTHY'
 
UNION ALL
 
-- PRODUCTION
SELECT
    tenant_id, 'PRODUCTION' AS domain,
    production_order AS entity_id, material AS entity_name,
    CASE WHEN days_late > 7 THEN 'CRITICAL'
         WHEN days_late > 0 THEN 'RISK'
         WHEN yield_var_pct < -0.10 THEN 'WATCH'
         ELSE 'GOOD' END                                          AS status,
    CASE WHEN days_late > 7 THEN 4 WHEN days_late > 0 THEN 3
         WHEN yield_var_pct < -0.10 THEN 2 ELSE 1 END             AS severity,
    open_qty                                                      AS metric_value,
    'Open quantity'                                             AS metric_label,
    CASE WHEN days_late > 0 THEN CONCAT('Order ', CAST(days_late AS STRING), ' days past finish date')
         WHEN yield_var_pct < -0.10 THEN 'Yield short of plan by >10%'
         ELSE 'On track' END                                      AS reason,
    CASE WHEN days_late > 7 THEN 'Re-sequence on line, check component shortage, expedite'
         WHEN days_late > 0 THEN 'Confirm new finish date, check capacity'
         WHEN yield_var_pct < -0.10 THEN 'Investigate scrap cause at work center, QM check'
         ELSE 'No action' END                                     AS recommended_action
FROM mv_ai_production_risk
 
UNION ALL
 
-- CASH / AR
SELECT
    tenant_id, 'CASH_AR' AS domain,
    customer AS entity_id, customer_name AS entity_name,
    CASE WHEN bucket_90plus > 0 THEN 'CRITICAL'
         WHEN bucket_61_90  > 0 THEN 'RISK'
         WHEN bucket_31_60  > 0 THEN 'WATCH'
         ELSE 'GOOD' END                                          AS status,
    CASE WHEN bucket_90plus > 0 THEN 4 WHEN bucket_61_90 > 0 THEN 3
         WHEN bucket_31_60 > 0 THEN 2 ELSE 1 END                  AS severity,
    total_open                                                   AS metric_value,
    'Open receivables'                                          AS metric_label,
    CONCAT('Max ', CAST(max_days_overdue AS STRING), ' days overdue')  AS reason,
    CASE WHEN bucket_90plus > 0 THEN 'Collections call today, consider delivery block / dunning'
         WHEN bucket_61_90  > 0 THEN 'Send reminder, confirm payment date'
         WHEN bucket_31_60  > 0 THEN 'Monitor, gentle reminder'
         ELSE 'No action' END                                     AS recommended_action
FROM mv_ai_ar_risk;;

-- KNMT — Customer-Material Info Record (VD59). One row per sales-org × channel × customer × material.
CREATE TABLE `KNMT` (
  `tenant_id`  varchar(20)    NOT NULL COMMENT "Multi-tenant identifier",
  `VKORG`      varchar(8)     NOT NULL COMMENT "Sales Organization",
  `VTWEG`      varchar(4)     NOT NULL COMMENT "Distribution Channel",
  `KUNNR`      varchar(20)    NOT NULL COMMENT "Customer Number",
  `MATNR`      varchar(80)    NOT NULL COMMENT "Material Number",
  `MANDT`      varchar(6)     NULL     COMMENT "SAP Client",
  `KDMAT`      varchar(70)    NULL     COMMENT "Customer Material Number",
  `POSAR`      varchar(2)     NULL     COMMENT "Item Usage",
  `KZTLF`      varchar(2)     NULL     COMMENT "Partial Delivery Indicator",
  `ANTLF`      decimal(5, 0)  NULL     COMMENT "Max Number of Partial Deliveries",
  `LPRIO`      varchar(4)     NULL     COMMENT "Delivery Priority",
  `VRKME`      varchar(6)     NULL     COMMENT "Sales Unit",
  `LFMNG`      decimal(13, 3) NULL     COMMENT "Minimum Delivery Quantity",
  `MFRGR`      varchar(18)    NULL     COMMENT "Material Freight Group",
  `LVORM`      varchar(2)     NULL     COMMENT "Deletion Flag",
  `ERDAT`      date           NULL     COMMENT "Created On",
  `created_at` datetime       NOT NULL COMMENT "ETL Pipeline Load Timestamp",
  `updated_at` datetime       NOT NULL COMMENT "ETL Pipeline Update Timestamp"
) ENGINE=OLAP
PRIMARY KEY(`tenant_id`, `VKORG`, `VTWEG`, `KUNNR`, `MATNR`)
COMMENT "SAP KNMT — lakehouse upsert, partition: none"
DISTRIBUTED BY HASH(`tenant_id`, `KUNNR`) BUCKETS 16
PROPERTIES (
  "colocate_with"           = "g_customer_v2",
  "compression"             = "LZ4",
  "enable_persistent_index" = "true",
  "fast_schema_evolution"   = "true",
  "replicated_storage"      = "true",
  "replication_num"         = "1"
);;

-- MKOL — Special Stocks with Vendor (MB54: vendor consignment / RTP). One row per material × plant × batch × special-stock-indicator × vendor.
CREATE TABLE `MKOL` (
  `tenant_id`  varchar(20)    NOT NULL COMMENT "Multi-tenant identifier",
  `MATNR`      varchar(80)    NOT NULL COMMENT "Material Number",
  `WERKS`      varchar(8)     NOT NULL COMMENT "Plant",
  `CHARG`      varchar(20)    NOT NULL COMMENT "Batch Number",
  `SOBKZ`      varchar(2)     NOT NULL COMMENT "Special Stock Indicator (K = Vendor Consignment, O = RTP at Vendor)",
  `LIFNR`      varchar(20)    NOT NULL COMMENT "Vendor Number",
  `MANDT`      varchar(6)     NULL     COMMENT "SAP Client",
  `LVORM`      varchar(2)     NULL     COMMENT "Deletion Flag",
  `ERSDA`      date           NULL     COMMENT "Created On",
  `SLABS`      decimal(13, 3) NULL     COMMENT "Consignment Unrestricted-Use Stock",
  `SINSM`      decimal(13, 3) NULL     COMMENT "Consignment Quality Inspection Stock",
  `SSPEM`      decimal(13, 3) NULL     COMMENT "Consignment Blocked Stock",
  `SEINM`      decimal(13, 3) NULL     COMMENT "Consignment Restricted-Use Stock",
  `created_at` datetime       NOT NULL COMMENT "ETL Pipeline Load Timestamp",
  `updated_at` datetime       NOT NULL COMMENT "ETL Pipeline Update Timestamp"
) ENGINE=OLAP
PRIMARY KEY(`tenant_id`, `MATNR`, `WERKS`, `CHARG`, `SOBKZ`, `LIFNR`)
COMMENT "SAP MKOL — lakehouse upsert, partition: none"
DISTRIBUTED BY HASH(`tenant_id`, `MATNR`) BUCKETS 16
PROPERTIES (
  "colocate_with"           = "g_material_v2",
  "compression"             = "LZ4",
  "enable_persistent_index" = "true",
  "fast_schema_evolution"   = "true",
  "replicated_storage"      = "true",
  "replication_num"         = "1"
);;
